#include <iostream>
using namespace std;

struct Guard {
    const char* name;
    Guard(const char* n) : name(n) { cout << "acquire " << name << endl; }
    ~Guard() { cout << "release " << name << endl; }
};

int main() {
    Guard g("file");
    cout << "working" << endl;
    return 0;
}
